    q: [['What will Saturday be like?', ['hot and dry', 'rainy', 'cold and windy'], 0], ['When is Lola meeting her friends?', ['at four on Saturday', 'on Sunday evening', 'at the gate at six'], 0], ['Why is it going to rain on Sunday?', ['the clouds on the map', 'the festival', 'it’s cold'], 0]]
